1	package com.example.starter.observation;
2	
3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.jdbc.core.RowMapper;
5	import org.springframework.stereotype.Repository;
6	
7	import java.util.Optional;
8	
9	/**
10	 * 幂等去重持久化：request_log 仅记录成功结果，与业务变更同事务原子提交；失败回滚不占键。
11	 */
12	@Repository
13	public class RequestLogRepository {
14	
15	    private static final RowMapper<RequestLogEntry> ENTRY_MAPPER = (rs, rowNum) -> new RequestLogEntry(
16	            rs.getString("request_id"),
17	            rs.getString("fingerprint"),
18	            rs.getString("operation"),
19	            (Integer) rs.getObject("response_status"),
20	            rs.getString("response_body"));
21	
22	    private final JdbcTemplate jdbcTemplate;
23	
24	    public RequestLogRepository(JdbcTemplate jdbcTemplate) {
25	        this.jdbcTemplate = jdbcTemplate;
26	    }
27	
28	    /**
29	     * 按请求标识查询去重记录；不存在时返回空。
30	     */
31	    public Optional<RequestLogEntry> find(String requestId) {
32	        return jdbcTemplate.query(
33	                        "SELECT request_id, fingerprint, operation, response_status, response_body "
34	                                + "FROM request_log WHERE request_id = ?",
35	                        ENTRY_MAPPER, requestId)
36	                .stream().findFirst();
37	    }
38	
39	    /**
40	     * 在写事务内先占位插入去重记录（响应暂为空），主键冲突时由数据库串行化并发同键请求。
41	     * 业务失败时随事务回滚，不占用该键。
42	     */
43	    public void insertPlaceholder(String requestId, String fingerprint, String operation) {
44	        jdbcTemplate.update(
45	                "INSERT INTO request_log (request_id, fingerprint, operation, response_status, response_body, created_at) "
46	                        + "VALUES (?, ?, ?, NULL, NULL, CURRENT_TIMESTAMP)",
47	                requestId, fingerprint, operation);
48	    }
49	
50	    /**
51	     * 业务成功后回填响应，与业务变更在同一事务内提交。
52	     */
53	    public void complete(String requestId, int responseStatus, String responseBody) {
54	        jdbcTemplate.update(
55	                "UPDATE request_log SET response_status = ?, response_body = ? WHERE request_id = ?",
56	                responseStatus, responseBody, requestId);
57	    }
58	}
